package com.cyclecare.app
import android.content.Context
import androidx.room.Room
import androidx.test.core.app.ApplicationProvider
import androidx.sqlite.db.SupportSQLiteDatabase
import com.cyclecare.app.data.local.*
import com.cyclecare.app.data.local.rust.*
import com.cyclecare.app.security.AuthPreferences
import kotlinx.coroutines.*
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config
import java.util.UUID
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34])
class ConflictStorageRoomTest {
 private val context:Context=ApplicationProvider.getApplicationContext();private val handles=mutableListOf<CycleCareDatabase>();private val names=mutableListOf<String>()
 private fun open():CycleCareDatabase{val name="outbox-${UUID.randomUUID()}";names+=name;return Room.databaseBuilder(context,CycleCareDatabase::class.java,name).allowMainThreadQueries().build().also{handles+=it;RustEnrollmentStage.schema(it.openHelper.writableDatabase);RustEnrollmentStage.senderSchema(it.openHelper.writableDatabase)}}
 @After fun close(){handles.forEach{it.close()};names.forEach{context.deleteDatabase(it)}}
 private fun entry(base:Long=7,attempts:Int=2)=HealthSyncOutboxEntry("owner","op","2026-10-01","UPSERT",base,17,"synthetic 🌸/\n",HealthSyncPayloadCodec.hash("synthetic 🌸/\n"),3,attempts,77,"OLD_ERROR","OLD_RECEIPT",45)
 private fun seed(db:CycleCareDatabase,e:HealthSyncOutboxEntry,server:Long=3,revision:Boolean=true){db.runInTransaction{val s=db.openHelper.writableDatabase;if(revision)s.execSQL("INSERT INTO health_sync_revisions(ownerId,recordId,revision,payloadHash,tombstone,updatedAt,serverRevision) VALUES(?,?,?,?,?,?,?)",arrayOf<Any>(e.ownerId,e.recordId,99,"KEEP_HASH",1,987,server));for(row in listOf(e,e.copy(operationId="sibling",revision=18),e.copy(operationId="different-base",baseRevision=e.baseRevision xor 1L),e.copy(operationId="other-record",recordId="2026-10-02"),e.copy(operationId="other-owner",ownerId="other"))){s.execSQL("INSERT INTO health_sync_outbox VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",arrayOf<Any?>(row.ownerId,row.operationId,row.recordId,row.kind,row.baseRevision,row.revision,row.payloadJson,row.payloadHash,row.consentGeneration,row.attempts,row.nextAttemptAt,row.lastError,row.serverReceipt,row.serverRevision))}}}
 private fun snapshot(db:CycleCareDatabase):List<List<String?>>{val out=mutableListOf<List<String?>>();for(table in listOf("cycle_day_logs","onboarding_profiles","cycle_settings","health_sync_revisions","health_sync_outbox","health_sync_conflicts","health_sync_cursors")){out+=listOf(table);db.openHelper.writableDatabase.query("SELECT * FROM $table ORDER BY 1,2").use{c->while(c.moveToNext())out+=(0 until c.columnCount).map{if(c.isNull(it))null else c.getString(it)}}};return out}

 private fun apply(db:CycleCareDatabase,e:HealthSyncOutboxEntry,native:Boolean,remote:Long=7,payload:String?="remote 🌸/\n\u0000tail",tombstone:Boolean=false,now:Long=999):Boolean{var result=false;db.runInTransaction{val s=db.openHelper.writableDatabase;result=if(native)RustConflictStorage.apply(s,e,remote,payload,tombstone,now)else RustOutboxRows.conflict(s,e,remote,payload,tombstone,now)};return result}
 @Test fun exactFullDatabaseOriginalLatestRevisionNullPayloadKindAndReplaceReset(){
  RustTrackNative.warmUp()
  for(local in listOf(Long.MIN_VALUE,0L,Long.MAX_VALUE))for(remote in listOf(0L,Long.MAX_VALUE))for(tombstone in listOf(false,true))for(payload in listOf<String?>(null,"remote 🌸/\n\u0000tail")){
   val a=open();val b=open();val e=entry();for(db in listOf(a,b)){seed(db,e);val sql=db.openHelper.writableDatabase;sql.execSQL("UPDATE health_sync_outbox SET revision=?,payloadJson=NULL,kind='DELETE' WHERE ownerId='owner' AND operationId='sibling'",arrayOf(local));sql.execSQL("INSERT INTO health_sync_conflicts VALUES('owner','2026-10-01','old',1,'old','UPSERT',2,'old',0,3,4,'OLD_RESOLUTION')")}
   assertEquals(apply(a,e,false,remote,payload,tombstone,Long.MAX_VALUE),apply(b,e,true,remote,payload,tombstone,Long.MAX_VALUE));assertEquals(snapshot(a),snapshot(b));val before=snapshot(b);assertTrue(apply(b,e,true,remote,payload,tombstone,Long.MAX_VALUE));assertEquals(before,snapshot(b));b.openHelper.writableDatabase.query("SELECT resolvedAt,resolution,remotePayloadJson,remoteTombstone FROM health_sync_conflicts WHERE ownerId='owner'").use{assertTrue(it.moveToFirst());assertTrue(it.isNull(0)&&it.isNull(1));assertEquals(payload,if(it.isNull(2))null else it.getString(2));assertEquals(if(tombstone)1 else 0,it.getInt(3))}
  }
 }
 @Test fun casMissAllFieldsAndInvalidRemoteOrTimeNoEffects(){RustTrackNative.warmUp();val db=open();val e=entry();seed(db,e);val before=snapshot(db);for(bad in listOf(e.copy(ownerId="absent"),e.copy(operationId="absent"),e.copy(recordId="different"),e.copy(revision=18),e.copy(baseRevision=8),e.copy(payloadHash="different"),e.copy(consentGeneration=4))){assertFalse(apply(db,bad,true));assertEquals(before,snapshot(db))};for(native in listOf(false,true))for((remote,now)in listOf(-1L to 0L,0L to -1L)){val ex=runCatching{apply(db,e.copy(operationId="absent"),native,remote=remote,now=now)}.exceptionOrNull();assertTrue(ex is IllegalArgumentException);assertEquals("Failed requirement.",ex?.message);assertEquals(before,snapshot(db))}}
 @Test fun beforeAfterInsertAndReplaceFaultsRollBackThenFreshRetry(){RustTrackNative.warmUp();for(existing in listOf(false,true))for(timing in listOf("BEFORE","AFTER")){val db=open();val e=entry();seed(db,e);val sql=db.openHelper.writableDatabase;if(existing)sql.execSQL("INSERT INTO health_sync_conflicts VALUES('owner','2026-10-01','old',1,'old','UPSERT',2,'old',0,3,4,'OLD')");val before=snapshot(db);sql.execSQL("CREATE TRIGGER fault $timing INSERT ON health_sync_conflicts BEGIN SELECT RAISE(ABORT,'conflict fault'); END");assertNotNull(runCatching{apply(db,e,true)}.exceptionOrNull());assertEquals(before,snapshot(db));sql.execSQL("DROP TRIGGER fault");assertTrue(apply(db,e,true))}}
 @Test fun privateSessionWrongOrderThreadClosedReentryAndOutcomeRefused(){
  RustTrackNative.warmUp();val db=open();val e=entry();seed(db,e);val sql=db.openHelper.writableDatabase;val before=snapshot(db);val field=RustConflictStorage::class.java.getDeclaredField("entered").apply{isAccessible=true};@Suppress("UNCHECKED_CAST")val entered=field.get(RustConflictStorage)as ThreadLocal<Boolean>;val cls=Class.forName("com.cyclecare.app.data.local.rust.RustConflictStorage\$Session");val ctor=cls.declaredConstructors.single().apply{isAccessible=true}
  fun call(session:Any,name:String,vararg args:Any):Any?{val m=cls.declaredMethods.single{it.name==name}.apply{isAccessible=true};return try{m.invoke(session,*args)}catch(e:java.lang.reflect.InvocationTargetException){throw e.cause!!}}
  val end=runCatching{db.runInTransaction{entered.set(true);val session=ctor.newInstance(sql,e,7L,"remote",true,99L);try{for(name in listOf("matches","latest","write"))assertNotNull(runCatching{call(session,name)}.exceptionOrNull());assertNotNull(runCatching{RustConflictStorage.apply(sql,e,7,"r",false,1)}.exceptionOrNull());val error=java.util.concurrent.atomic.AtomicReference<Throwable>();val t=Thread{try{call(session,"ready")}catch(e:Throwable){error.set(e)}};t.start();t.join(5000);assertFalse(t.isAlive);assertTrue(error.get()is IllegalStateException);call(session,"ready");assertNotNull(runCatching{call(session,"outcome",1)}.exceptionOrNull());assertEquals(true,call(session,"matches"));assertNotNull(runCatching{call(session,"write")}.exceptionOrNull());call(session,"latest");call(session,"write");assertNotNull(runCatching{call(session,"outcome",0)}.exceptionOrNull());assertEquals(true,call(session,"outcome",1));call(session,"close");assertNotNull(runCatching{call(session,"outcome",1)}.exceptionOrNull());throw IllegalStateException("adversarial rollback")}finally{call(session,"close");entered.remove()}}}.exceptionOrNull();assertEquals("adversarial rollback",end?.message);assertEquals(before,snapshot(db))
 }
 @Test fun actualHostOriginalRollbackControlFullDatabaseAndConsentIdentityRefusal()=runBlocking{
  RustTrackNative.warmUp();val db=open();val e=entry();seed(db,e);val prefs=AuthPreferences(context,context.getSharedPreferences("conflict-${UUID.randomUUID()}",Context.MODE_PRIVATE),true).apply{userId="owner";isCloudSyncAllowed=true;check(saveServerHealthConsentReceipt("owner",sessionGeneration,healthConsentGeneration,31,true))};val h=RustBoundRoomHost(prefs);val token=(h.publish(null,db,prefs.rustOperationSnapshot())as RustBoundRoomHost.Result.Value).value;val initial=snapshot(db);var expected:List<List<String?>>?=null;val control=runCatching{db.runInTransaction{RustOutboxRows.conflict(db.openHelper.writableDatabase,e,8,"remote",true,999);expected=snapshot(db);throw IllegalStateException("original rollback")}}.exceptionOrNull();assertEquals("original rollback",control?.message);assertEquals(initial,snapshot(db))
  suspend fun call(server:Long=31)=withContext(Dispatchers.IO){h.conflictSync(token,server,e,8,"remote",true,999)}
  assertEquals(RustBoundRoomHost.Result.Stale,call(32));assertEquals(initial,snapshot(db));val result=call();assertTrue(result is RustBoundRoomHost.Result.Value&&result.value);assertEquals(expected,snapshot(db));prefs.markPendingHealthSyncRevoke();assertEquals(RustBoundRoomHost.Result.Stale,call());assertEquals(expected,snapshot(db));prefs.userId="other";assertEquals(RustBoundRoomHost.Result.Stale,call());assertEquals(expected,snapshot(db))
 }
}
